import{_ as i,o as a,c as n,aj as t}from"./chunks/framework.BdtAaXf2.js";const e="/assets/image-20250924094139996.B2PZFbaG.png",l="/assets/PixPin_2025-09-24_09-44-36.BcfCsEOk.gif",p="/assets/image-20250924095550254.BC4QzH04.png",r="/assets/image-20250924095625515.CWmBOGkv.png",h="/assets/image-20250924100019210.9BR9kEJ4.png",k="/assets/PixPin_2025-09-24_09-44-36.BcfCsEOk.gif",m=JSON.parse('{"title":"HarmonyOS 共建能力实践征文 青蓝萤火故事屋-Swiper","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS 共建能力实践征文 青蓝萤火故事屋-Swiper/HarmonyOS 共建能力实践征文 青蓝萤火故事屋-Swiper.md","filePath":"鸿蒙开发技巧/HarmonyOS 共建能力实践征文 青蓝萤火故事屋-Swiper/HarmonyOS 共建能力实践征文 青蓝萤火故事屋-Swiper.md","lastUpdated":1759102800000,"__rawMarkdown":"# HarmonyOS 共建能力实践征文 青蓝萤火故事屋-Swiper\\n\\n> 作者：万少\\n\\n## 前言\\n\\n**青蓝萤火故事屋** 是已经上架到HarmonyOS应用市场的鸿蒙应用，它支持HarmonyOS 5+设备访问使用，也就是俗称的纯血鸿蒙。\\n\\n界面一览如下。\\n\\n![image-20250924094139996](assets/image-20250924094139996.png)\\n\\n\\n\\n## Swiper介绍\\n\\n[Swiper](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-swiper)组件提供滑动轮播显示的能力。Swiper本身是一个容器组件，当设置了多个子组件后，可以对这些子组件进行轮播显示。通常，在一些应用首页显示推荐的内容时，需要用到轮播显示的能力。\\n\\n![PixPin_2025-09-24_09-44-36](assets/PixPin_2025-09-24_09-44-36.gif)\\n\\n其中系统也提供了基础、系统的Swiper属性，如下表所示。\\n\\n### 基础功能属性\\n\\n| 属性         | 类型    | 默认值 | 描述                 | 使用场景                         |\\n| ------------ | ------- | ------ | -------------------- | -------------------------------- |\\n| **index**    | number  | 0      | 当前显示的子组件索引 | 控制初始显示页面或跳转到指定页面 |\\n| **loop**     | boolean | true   | 是否循环播放         | 需要无限轮播时开启               |\\n| **autoplay** | boolean | false  | 是否自动轮播         | 需要自动切换内容时               |\\n| **interval** | number  | 3000   | 自动轮播间隔（毫秒） | 控制自动播放速度                 |\\n| **duration** | number  | 400    | 滑动动画时长（毫秒） | 调整切换动画的流畅度             |\\n| **vertical** | boolean | false  | 是否为纵向滑动       | 实现垂直方向的轮播               |\\n\\n### 显示控制属性\\n\\n| 属性             | 类型          | 默认值 | 描述                       | 使用场景               |\\n| ---------------- | ------------- | ------ | -------------------------- | ---------------------- |\\n| **displayCount** | number        | 1      | 每页显示的子组件数量       | 实现多卡片并排显示     |\\n| **itemSpace**    | number        | 0      | 子组件之间的间距           | 调整卡片间的距离       |\\n| **prevMargin**   | number/string | 0      | 前边距，露出前一项部分内容 | 实现\\"预览\\"效果         |\\n| **nextMargin**   | number/string | 0      | 后边距，露出后一项部分内容 | 实现\\"预览\\"效果         |\\n| **cachedCount**  | number        | -1     | 预加载的子组件数量         | 优化性能，减少滑动卡顿 |\\n\\n### 导航指示器属性\\n\\n| 属性               | 类型    | 默认值 | 描述                 | 使用场景           |\\n| ------------------ | ------- | ------ | -------------------- | ------------------ |\\n| **indicator**      | boolean | true   | 是否显示导航点指示器 | 基本的页码指示     |\\n| **indicatorStyle** | Object  | -      | 自定义指示器样式     | 个性化导航点外观   |\\n| **digital**        | boolean | false  | 是否启用数字导航点   | 需要显示具体页码时 |\\n| **displayArrow**   | boolean | false  | 是否显示导航箭头     | 需要明确的切换指引 |\\n\\n### 交互控制属性\\n\\n| 属性             | 类型    | 默认值 | 描述                 | 使用场景           |\\n| ---------------- | ------- | ------ | -------------------- | ------------------ |\\n| **disableSwipe** | boolean | false  | 是否禁止用户滑动操作 | 只允许程序控制切换 |\\n| **disableTouch** | boolean | false  | 是否禁止触摸操作     | 完全禁用用户交互   |\\n| **nestedScroll** | Object  | -      | 嵌套滚动模式配置     | 处理内外滚动冲突   |\\n\\n### 动画效果属性\\n\\n| 属性                        | 类型     | 默认值   | 描述           | 使用场景                 |\\n| --------------------------- | -------- | -------- | -------------- | ------------------------ |\\n| **curve**                   | Curve    | Linear   | 动画曲线       | 控制切换动画的缓动效果   |\\n| **scrollEffect**            | string   | \\"spring\\" | 滑动边缘效果   | 设置滑动到边缘的回弹效果 |\\n| **customContentTransition** | function | -        | 自定义切换动画 | 实现复杂的过渡动画       |\\n\\n## 然而\\n\\n但是在实际开发中，往往需要我们根据业务的需求，需要对Swiper进行基本的定制或者简化它的使用步骤，比如以下需求。\\n\\n- ✅ 自动播放功能，可配置播放间隔\\n- ✅ 多种指示点位置选择（顶部/底部，左/中/右）\\n- ✅ 手势滑动支持，触摸时自动暂停播放\\n- ✅ 响应式设计，自动适应不同屏幕尺寸\\n- ✅ 支持图片标题和描述显示\\n- ✅ 渐变遮罩效果\\n- ✅ 循环播放支持\\n- ✅ 优雅的动画过渡效果\\n- ✅ 空状态处理\\n\\n\\n\\n\\n\\n## 第三方的Swiper组件\\n\\n[Swiper 轮播组件](https://gitee.com/yang-zhixue/swiper-lib#swiperitem) 是一个第三方的Swiper组件，它支持HarmonyOS 5系统，API版本16以及以上，V1状态管理器，并且针对常见的Swiper使用需求进行了封装，比如：\\n\\n- ✅ 自动播放功能，可配置播放间隔\\n- ✅ 多种指示点位置选择（顶部/底部，左/中/右）\\n- ✅ 手势滑动支持，触摸时自动暂停播放\\n- ✅ 响应式设计，自动适应不同屏幕尺寸\\n- ✅ 支持图片标题和描述显示\\n- ✅ 渐变遮罩效果\\n- ✅ 循环播放支持\\n- ✅ 优雅的动画过渡效果\\n- ✅ 空状态处理\\n\\n\\n\\n## 使用步骤\\n\\n### 1. 下载Har\\n\\nSwiper轮播组件没有上架到三方市场，所以需要我们下载它Har包的形式使用。\\n\\n![image-20250924095550254](assets/image-20250924095550254.png)\\n\\n然后得到本地文件 **SwiperLib.har** ，如图所示。\\n\\n![image-20250924095625515](assets/image-20250924095625515.png)\\n\\n### 2. 拷贝SwiperLib.har 到自己的工程目录中\\n\\n因为并没有上传到三方库中，所以需要自己拷贝到工程中，如图所示。\\n\\n![image-20250924100019210](assets/image-20250924100019210.png)\\n\\n### 3. 工程中引入\\n\\n然后在自己工程都模块中来引入它\\n\\n> entry/oh-package.json5\\n\\n```json\\n{\\n  \\"name\\": \\"entry\\",\\n  \\"version\\": \\"1.0.0\\",\\n  \\"description\\": \\"Please describe the basic information.\\",\\n  \\"main\\": \\"\\",\\n  \\"author\\": \\"\\",\\n  \\"license\\": \\"\\",\\n  \\"dependencies\\": {\\n    \\"@hzw/zrouter\\": \\"^1.6.0\\",\\n    \\"swiperlib\\": \\"file:../SwiperLib.har\\"\\n  },\\n  \\"devDependencies\\": {},\\n  \\"dynamicDependencies\\": {}\\n}\\n```\\n\\n### 4. 然后在页面中直接使用即可\\n\\n#### 1. 引入相关模块\\n\\n```typescript\\nimport { IndicatorPosition, SwiperComponent, SwiperItem } from \'swiperlib\';\\n```\\n\\n#### 2. 初始化数据\\n\\n需要注意的时，该组件目前只支持网络图片，还不支持本地图片😒，如果要用到网络图片，需要在modules.json5文件中声明网络权限\\n\\n```typescript\\n@State private swiperData: SwiperItem[] = [\\n    {\\n      id: `swiper_${Date.now()}_1`,\\n      imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner1.png?x-image-process=style/style-ys\\",\\n      title: \\"标题1\\"\\n    }, {\\n    id: `swiper_${Date.now()}_2`,\\n    imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner2.png?x-image-process=style/style-ys\\",\\n    title: \\"标题2\\"\\n  }, {\\n    id: `swiper_${Date.now()}_3`,\\n    imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner3.png?x-image-process=style/style-ys\\",\\n    title: \\"标题3\\"\\n  }, {\\n    id: `swiper_${Date.now()}_4`,\\n    imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner4.png?x-image-process=style/style-ys\\",\\n    title: \\"标题4\\"\\n  }, {\\n    id: `swiper_${Date.now()}_5`,\\n    imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner5.png?x-image-process=style/style-ys\\",\\n    title: \\"标题5\\"\\n  },\\n\\n  ];\\n```\\n\\n#### 3. 渲染\\n\\n```tsx\\n  SwiperComponent({\\n    dataSource: this.swiperData,\\n    autoPlay: true,\\n    autoPlayInterval: 3000,\\n    componentHeight: \\"200vp\\",\\n    showIndicator: true,\\n    indicatorPosition: IndicatorPosition.BOTTOM_CENTER\\n  })\\n```\\n\\n#### 4. 效果\\n\\n![PixPin_2025-09-24_09-44-36](assets/PixPin_2025-09-24_09-44-36-1758679510900.gif)\\n\\n#### 5. 完整示例代码\\n\\n```json\\nimport { IndicatorPosition, SwiperComponent, SwiperItem } from \'swiperlib\';\\n\\n@Component\\n@Entry\\nstruct Index {\\n  @State private swiperData: SwiperItem[] = [\\n    {\\n      id: `swiper_${Date.now()}_1`,\\n      imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner1.png?x-image-process=style/style-ys\\",\\n      title: \\"标题1\\"\\n    }, {\\n    id: `swiper_${Date.now()}_2`,\\n    imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner2.png?x-image-process=style/style-ys\\",\\n    title: \\"标题2\\"\\n  }, {\\n    id: `swiper_${Date.now()}_3`,\\n    imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner3.png?x-image-process=style/style-ys\\",\\n    title: \\"标题3\\"\\n  }, {\\n    id: `swiper_${Date.now()}_4`,\\n    imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner4.png?x-image-process=style/style-ys\\",\\n    title: \\"标题4\\"\\n  }, {\\n    id: `swiper_${Date.now()}_5`,\\n    imageUrl: \\"https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/tmp/home_banner5.png?x-image-process=style/style-ys\\",\\n    title: \\"标题5\\"\\n  },\\n\\n  ];\\n\\n  build() {\\n    Column() {\\n      SwiperComponent({\\n        dataSource: this.swiperData,\\n        autoPlay: true,\\n        autoPlayInterval: 3000,\\n        componentHeight: \\"200vp\\",\\n        showIndicator: true,\\n        indicatorPosition: IndicatorPosition.BOTTOM_CENTER\\n      })\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n## 其他功能\\n\\n### 基础轮播\\n\\n```\\nSwiperComponent({\\n  dataSource: swiperData,\\n  autoPlay: true,\\n  autoPlayInterval: 3000,\\n  showIndicator: true,\\n  indicatorPosition: IndicatorPosition.BOTTOM_CENTER\\n})\\n```\\n\\n### 自定义样式\\n\\n```\\nSwiperComponent({\\n  dataSource: swiperData,\\n  componentHeight: \\"150vp\\",\\n  componentWidth: \\"80%\\",\\n  componentBorderRadius: \\"16vp\\",\\n  componentMargin: \\"20vp\\"\\n})\\n```\\n\\n### 禁用自动播放\\n\\n```\\nSwiperComponent({\\n  dataSource: swiperData,\\n  autoPlay: false,\\n  showIndicator: true\\n})\\n```\\n\\n### 顶部指示点\\n\\n```\\nSwiperComponent({\\n  dataSource: swiperData,\\n  indicatorPosition: IndicatorPosition.TOP_RIGHT\\n})\\n```\\n\\n## 最佳实践\\n\\n### 1. 数据源管理\\n\\n```\\n@State private swiperData: SwiperItem[] = [];\\n\\n// 推荐：使用唯一ID\\nprivate loadSwiperData() {\\n  this.swiperData = [\\n    {\\n      id: `swiper_${Date.now()}_1`,\\n      imageUrl: \\"https://example.com/image1.jpg\\",\\n      title: \\"标题1\\"\\n    }\\n  ];\\n}\\n```\\n\\n### 2. 性能优化\\n\\n```\\n// 推荐：合理设置自动播放间隔\\nSwiperComponent({\\n  autoPlayInterval: 4000, // 不要设置过短的间隔\\n  loop: true // 启用循环播放提升用户体验\\n})\\n```\\n\\n### 3. 响应式设计\\n\\n```\\n// 推荐：使用相对单位\\nSwiperComponent({\\n  componentHeight: \\"30%\\", // 相对于父容器\\n  componentWidth: \\"100%\\"\\n})\\n```\\n\\n### 4. 错误处理\\n\\n```\\n// 推荐：提供默认图片\\nlet swiperData: SwiperItem[] = data.map((item, index) => ({\\n  id: item.id || `default_${index}`,\\n  imageUrl: item.imageUrl || \\"/common/images/default.png\\",\\n  title: item.title || \\"默认标题\\",\\n  description: item.description\\n}));\\n```\\n\\n### 注意事项\\n\\n1. **图片资源**：确保图片URL有效，建议提供备用图片\\n2. **数据唯一性**：每个SwiperItem需要唯一的id\\n3. **性能考虑**：避免同时加载过多大尺寸图片\\n4. **内存管理**：组件会自动管理定时器生命周期\\n5. **触摸交互**：用户触摸时会暂停自动播放\\n\\n\\n\\n\\n\\n"}'),o={name:"鸿蒙开发技巧/HarmonyOS 共建能力实践征文 青蓝萤火故事屋-Swiper/HarmonyOS 共建能力实践征文 青蓝萤火故事屋-Swiper.md"};function d(c,s,E,g,y,u){return a(),n("div",null,[...s[0]||(s[0]=[t("",71)])])}const F=i(o,[["render",d]]);export{m as __pageData,F as default};
